/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountEmailTypoFix, type EmailTypoFixOptions } from "../../components/email-typo-fix/EmailTypoFixEngine.js";
import type { MotionController } from "../../components/email-typo-fix/motion-runtime";

export function EmailTypoFix({ options, className }: { options?: EmailTypoFixOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountEmailTypoFix(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="email-typo-fix" />;
}

